def render(board, pastel:)
  divider = pastel.dim("\n───┼───┼───\n")
  grid = board.rows.each_with_index.map { |row, r|
    row.each_with_index.map { |cell, c|
      glyph(cell, (r * Board::SIZE) + c, pastel)
    }.join(pastel.dim("│"))
  }.join(divider)
  TTY::Box.frame(grid, title: { top_left: " Tic Tac Toe " }, padding: [0, 2], border: :thick)
end

